// Extract fields from the incoming Shiny payload
const body = $input.first().json.body || $input.first().json;
const message    = body.message    || '';
const session_id = body.session_id || 'unknown';
const timestamp  = body.timestamp  || new Date().toISOString();

if (!message.trim()) {
  throw new Error('Empty message received');
}

return [{ json: { message, session_id, timestamp } }];

// Extract the text from Gemini's response
const geminiOutput = $input.first().json;

// Gemini node returns the text directly as 'text' or nested in 'content'
const reply = geminiOutput.text
  || geminiOutput?.content?.parts?.[0]?.text
  || geminiOutput?.candidates?.[0]?.content?.parts?.[0]?.text
  || '🤖 Sorry, I could not generate a response. Please call REG on +250 252 570 720.';

return [{ json: { reply: reply.trim() } }];
